import sys, json, logging

def _sanitize_json_text(text: str) -> str:
    # Truncate to last closing brace/bracket to remove trailing noise
    last_obj = text.rfind('}')
    last_arr = text.rfind(']')
    cut = max(last_obj, last_arr)
    return text[:cut+1] if cut != -1 else text


def main():
