        except json.JSONDecodeError as e:
            try:
                cfg = json.loads(_sanitize_json_text(raw))
            except json.JSONDecodeError as e2:
                msg = f"Error parsing JSON response: {e2.msg}: line {getattr(e2, 'lineno', '?')} column {getattr(e2, 'colno', '?')} (char {getattr(e2, 'pos', '?')})"
